// Package picojson implements the ProtoJSON mapping for messages generated by
// protoc-gen-pico with the protojson=true option.
//
// It converts through the binary wire format: Marshal encodes the message
// with picobuf and renders the wire data as JSON, and Unmarshal parses the
// JSON into wire data and decodes that with picobuf. Custom types therefore
// map to JSON as the protobuf type they are declared as.
//
// picojson is experimental for the time being: its API and the generated
// schema may change in incompatible ways.
package picojson

import (
	"errors"
	"fmt"

	"storj.io/picobuf"
	"storj.io/picobuf/internal/protowire"
)

// Schema describes the messages and enums that a generated file refers to.
// It is a generated string constant, so it needs no initialization and holds
// no pointers. Messages and enums refer to each other by their byte offset in
// the schema.
//
// A message is its name, its number of fields, and its fields in declaration
// order. A field is
//
//	number kind flags [oneof] [type] name [jsonName]
//
// where oneof is present with flagOneof, type is the offset of the message or
// enum for those kinds, and jsonName is present with flagJSONName; otherwise
// it equals name. An enum is its name, its number of values, and the number
// and name of each value in declaration order.
//
// Kind and flags are bytes, enum value numbers are zigzag varints, and
// everything else is a varint. A name is a varint n followed by n>>1 bytes
// when n is even. When n is odd, the name is the one at offset n>>1, which
// repeats text from earlier in the schema.
type Schema string

// Field flags.
const (
	flagList = 1 << iota
	flagMap
	flagPresence
	flagOneof
	flagJSONName
)

// Kind is a protobuf field kind. The values match protoreflect.Kind.
type Kind uint8

// Supported field kinds.
const (
	doubleKind   Kind = 1
	floatKind    Kind = 2
	int64Kind    Kind = 3
	uint64Kind   Kind = 4
	int32Kind    Kind = 5
	fixed64Kind  Kind = 6
	fixed32Kind  Kind = 7
	boolKind     Kind = 8
	stringKind   Kind = 9
	messageKind  Kind = 11
	bytesKind    Kind = 12
	uint32Kind   Kind = 13
	enumKind     Kind = 14
	sfixed32Kind Kind = 15
	sfixed64Kind Kind = 16
	sint32Kind   Kind = 17
	sint64Kind   Kind = 18
)

// Marshal encodes msg, described by the message at offset in s, as ProtoJSON.
func Marshal(msg picobuf.Message, s Schema, offset int) ([]byte, error) {
	wire, err := picobuf.Marshal(msg)
	if err != nil {
		return nil, err
	}
	// ponytail: 2x wire size fits most messages; growth handles the rest.
	m := marshaler{schema: s, out: make([]byte, 0, 2*len(wire)+16)}
	if err := m.message(int32(offset), wire); err != nil {
		return nil, fmt.Errorf("picojson: %w", err)
	}
	return m.out, nil
}

// Unmarshal decodes ProtoJSON data into msg, described by the message at
// offset in s. Like protojson, it rejects unknown fields.
func Unmarshal(data []byte, msg picobuf.Message, s Schema, offset int) error {
	wire, err := unmarshalWire(data, s, int32(offset))
	if err != nil {
		return fmt.Errorf("picojson: %w", err)
	}
	return picobuf.Unmarshal(wire, msg)
}

// Errors inside the package have no prefix, Marshal and Unmarshal add it.
var errSyntax = errors.New("invalid wire data")

func fieldError(msg *message, field *field, err error) error {
	return fmt.Errorf("%s.%s: %w", msg.Name, msg.text(field.name), err)
}

// reader decodes a schema from pos.
type reader struct {
	s   Schema
	pos int
}

func (r *reader) byte() byte {
	b := r.s[r.pos]
	r.pos++
	return b
}

func (r *reader) uvarint() uint64 {
	var x uint64
	for shift := 0; ; shift += 7 {
		b := r.byte()
		x |= uint64(b&0x7f) << shift
		if b < 0x80 {
			return x
		}
	}
}

func (r *reader) int32() int32 { return int32(r.uvarint()) }

// name skips a name and returns the offset of its text.
func (r *reader) name() int {
	at := r.pos
	n := int(r.uvarint())
	if n&1 != 0 {
		return n >> 1
	}
	r.pos += n >> 1
	return at
}

func (r *reader) string() string { return r.s.text(r.name()) }

// text returns the name at offset.
func (s Schema) text(offset int) string {
	r := reader{s: s, pos: offset}
	n := int(r.uvarint()) >> 1
	return string(s[r.pos : r.pos+n])
}

type message struct {
	Name  string
	count int
	// fields is positioned at the first field.
	fields reader
}

type field struct {
	Number   int32
	Kind     Kind
	List     bool
	Map      bool
	Presence bool
	// Oneof is the 1-based index of the containing oneof, or zero.
	Oneof int32
	// Type is the offset of the message or enum of the field.
	Type int32
	// name and jsonName are the offsets of the names, see Schema.text.
	name, jsonName int
}

func (s Schema) message(offset int32) message {
	r := reader{s: s, pos: int(offset)}
	name := r.string()
	count := int(r.uvarint())
	return message{Name: name, count: count, fields: r}
}

func (m *message) text(offset int) string { return m.fields.s.text(offset) }

// iter iterates over the fields of a message.
type iter struct {
	r    reader
	left int
}

func (m *message) iter() iter { return iter{r: m.fields, left: m.count} }

func (it *iter) next() (field, bool) {
	if it.left == 0 {
		return field{}, false
	}
	it.left--
	r := &it.r
	f := field{Number: r.int32(), Kind: Kind(r.byte())}
	flags := r.byte()
	f.List, f.Map, f.Presence = flags&flagList != 0, flags&flagMap != 0, flags&flagPresence != 0
	if flags&flagOneof != 0 {
		f.Oneof = r.int32()
	}
	if f.Kind == messageKind || f.Kind == enumKind {
		f.Type = r.int32()
	}
	f.name = r.name()
	f.jsonName = f.name
	if flags&flagJSONName != 0 {
		f.jsonName = r.name()
	}
	return f, true
}

// find advances to the field with the given number. If there is none after
// the current position, it returns false and does not advance.
func (it *iter) find(number int32) (field, bool) {
	probe := *it
	for {
		f, ok := probe.next()
		if !ok {
			return field{}, false
		}
		if f.Number == number {
			*it = probe
			return f, true
		}
	}
}

// first returns the first field, the value of a wrapper.
func (m *message) first() field {
	it := m.iter()
	f, _ := it.next()
	return f
}

// fieldByNumber returns the field with the given number.
func (m *message) fieldByNumber(number int32) (field, bool) {
	it := m.iter()
	return it.find(number)
}

// indexByNumber returns the index of the field with the given number, or -1.
func (m *message) indexByNumber(number int32) int {
	it := m.iter()
	for i := 0; ; i++ {
		f, ok := it.next()
		if !ok {
			return -1
		}
		if f.Number == number {
			return i
		}
	}
}

// nameLookup scans fields in declaration order until a name requires a
// restart. It then indexes both spellings, keeping arbitrary JSON field
// order linear without allocating an index for the usual ordered input.
type nameLookup struct {
	msg    *message
	it     iter
	index  map[string]int
	fields []field
}

func (l *nameLookup) find(name string) (int, field, bool) {
	if l.index == nil {
		for {
			i := l.msg.count - l.it.left
			f, ok := l.it.next()
			if !ok {
				break
			}
			if l.msg.text(f.jsonName) == name || l.msg.text(f.name) == name {
				return i, f, true
			}
		}
		l.index = make(map[string]int, l.msg.count)
		l.fields = make([]field, l.msg.count)
		it := l.msg.iter()
		for i := 0; i < l.msg.count; i++ {
			f, _ := it.next()
			l.fields[i] = f
			for _, offset := range [...]int{f.jsonName, f.name} {
				key := l.msg.text(offset)
				if _, exists := l.index[key]; !exists {
					l.index[key] = i
				}
			}
		}
	}
	i, ok := l.index[name]
	if !ok {
		return -1, field{}, false
	}
	return i, l.fields[i], true
}

// enumName returns the name of the first value of the enum at offset with
// the given number.
func (s Schema) enumName(offset, number int32) (string, bool) {
	r := reader{s: s, pos: int(offset)}
	r.string()
	for n := r.uvarint(); n > 0; n-- {
		v, name := protowire.DecodeZigZag(r.uvarint()), r.string()
		if int32(v) == number {
			return name, true
		}
	}
	return "", false
}

// enumNumber returns the number of the value of the enum at offset with the
// given name.
func (s Schema) enumNumber(offset int32, name string) (int32, bool) {
	r := reader{s: s, pos: int(offset)}
	r.string()
	for n := r.uvarint(); n > 0; n-- {
		v, vname := protowire.DecodeZigZag(r.uvarint()), r.string()
		if vname == name {
			return int32(v), true
		}
	}
	return 0, false
}
